def is_palindrome(s):
    s = ''.join(c for c in s if c.isalnum()).lower()
    return s == s[::-1]

def is_palindrome(s):
    cleaned = s.replace(" ", "").lower()
    return cleaned == cleaned[::-1]

def is_palindrome(s):
    s_clean = s.replace(" ", "").lower()
    return s_clean == s_clean[::-1]

